def clear():
    os.system("cls" if os.name == "nt" else "clear")

def get_time_greeting():
    h = datetime.datetime.now().hour
    if h < 6 or h >= 22:
        return "You're up late"
    if h < 12:
        return "Good morning"
    if h < 18:
        return "Good afternoon"
    return "Good evening"

