def draw_butterfly(n=4):
    lines = []
    for i in range(n):
        left = "*" * (i + 1)
        right = "*" * (i + 1)
        lines.append(left + " " * (2 * (n - i - 1)) + right)
    for i in range(n - 1, -1, -1):
        left = "*" * (i + 1)
        right = "*" * (i + 1)
        lines.append(left + " " * (2 * (n - i - 1)) + right)
    return "\n".join(lines)

