def convert_seconds(seconds):
    days = seconds // 86400
    hours = (seconds % 86400) // 3600
    minutes = (seconds % 3600) // 60
    secs = seconds % 60
    return "{}d {}h {}m {}s".format(days, hours, minutes, secs)

def generate_random_data(size=10):
    return [random.randint(1, 100) for _ in range(size)]

def random_shuffle_list(items):
    lst = items.copy()
    random.shuffle(lst)
    return lst

def flatten_list(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten_list(item))
        else:
            result.append(item)
    return result

def chunk_list(lst, size):
    return [lst[i:i+size] for i in range(0, len(lst), size)]

def unique_elements(lst):
    seen = set()
    result = []
    for item in lst:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def list_intersection(a, b):
    return list(set(a) & set(b))

def list_union(a, b):
    return list(set(a) | set(b))

def list_difference(a, b):
    return list(set(a) - set(b))

def list_symmetric_difference(a, b):
    return list(set(a) ^ set(b))

def rotate_list(lst, n):
    n = n % len(lst) if lst else 0
    return lst[n:] + lst[:n]

def find_all_indexes(lst, value):
    return [i for i, x in enumerate(lst) if x == value]

def split_evens_odds(nums):
    evens = [x for x in nums if x % 2 == 0]
    odds = [x for x in nums if x % 2 != 0]
    return evens, odds

def sum_digits(n):
    return sum(int(d) for d in str(abs(n)))

def reverse_number(n):
    return int(str(abs(n))[::-1]) * (-1 if n < 0 else 1)

def is_armstrong(n):
    digits = [int(d) for d in str(n)]
    return sum(d ** len(digits) for d in digits) == n

def is_perfect_number(n):
    if n < 2:
        return False
    divisors = [i for i in range(1, n) if n % i == 0]
    return sum(divisors) == n

def is_happy_number(n):
    seen = set()
    while n != 1 and n not in seen:
        seen.add(n)
        n = sum(int(d) ** 2 for d in str(n))
    return n == 1

def collatz_sequence(n):
    seq = [n]
    while n != 1:
        if n % 2 == 0:
            n //= 2
        else:
            n = 3 * n + 1
        seq.append(n)
    return seq

def sieve_of_eratosthenes(limit):
    primes = [True] * (limit + 1)
    primes[0] = primes[1] = False
    for i in range(2, int(limit ** 0.5) + 1):
        if primes[i]:
            for j in range(i * i, limit + 1, i):
                primes[j] = False
    return [i for i, p in enumerate(primes) if p]

def nth_prime(n):
    count = 0
    num = 2
    while True:
        if is_prime(num):
            count += 1
            if count == n:
                return num
        num += 1

def goldbach_conjecture(n):
    if n < 4 or n % 2 != 0:
        return None
    primes = sieve_of_eratosthenes(n)
    for p in primes:
        if n - p in primes:
            return (p, n - p)
    return None

def euler_totient(n):
    result = n
    p = 2
    temp = n
    while p * p <= temp:
        if temp % p == 0:
            while temp % p == 0:
                temp //= p
            result -= result // p
        p += 1
    if temp > 1:
        result -= result // temp
    return result

def extended_gcd(a, b):
    if b == 0:
        return a, 1, 0
    g, x1, y1 = extended_gcd(b, a % b)
    return g, y1, x1 - (a // b) * y1

def modular_inverse(a, m):
    g, x, _ = extended_gcd(a, m)
    if g != 1:
        return None
    return x % m

def matrix_multiply(a, b):
    rows_a, cols_a = len(a), len(a[0])
    rows_b, cols_b = len(b), len(b[0])
    if cols_a != rows_b:
        return None
    result = [[0 for _ in range(cols_b)] for _ in range(rows_a)]
    for i in range(rows_a):
        for j in range(cols_b):
            for k in range(cols_a):
                result[i][j] += a[i][k] * b[k][j]
    return result

def matrix_transpose(m):
    return [[m[j][i] for j in range(len(m))] for i in range(len(m[0]))]

def matrix_determinant(m):
    n = len(m)
    if n == 1:
        return m[0][0]
    if n == 2:
        return m[0][0] * m[1][1] - m[0][1] * m[1][0]
    det = 0
    for j in range(n):
        sub = [[m[i][k] for k in range(n) if k != j] for i in range(1, n)]
        det += m[0][j] * ((-1) ** j) * matrix_determinant(sub)
    return det

def dot_product(a, b):
    return sum(x * y for x, y in zip(a, b))

def cross_product(a, b):
    if len(a) != 3 or len(b) != 3:
        return None
    return [
        a[1] * b[2] - a[2] * b[1],
        a[2] * b[0] - a[0] * b[2],
        a[0] * b[1] - a[1] * b[0]
    ]

def vector_magnitude(v):
    return math.sqrt(sum(x * x for x in v))

def euclidean_distance(p1, p2):
    return math.sqrt(sum((a - b) ** 2 for a, b in zip(p1, p2)))

def manhattan_distance(p1, p2):
    return sum(abs(a - b) for a, b in zip(p1, p2))

def hamming_distance(s1, s2):
    if len(s1) != len(s2):
        return -1
    return sum(1 for a, b in zip(s1, s2) if a != b)

def levenshtein_distance(s1, s2):
    if len(s1) < len(s2):
        return levenshtein_distance(s2, s1)
    if len(s2) == 0:
        return len(s1)
    prev = list(range(len(s2) + 1))
    for i, c1 in enumerate(s1):
        curr = [i + 1]
        for j, c2 in enumerate(s2):
            cost = 0 if c1 == c2 else 1
            curr.append(min(curr[j] + 1, prev[j + 1] + 1, prev[j] + cost))
        prev = curr
    return prev[-1]

def to_base(n, base):
    if n == 0:
        return "0"
    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result = ""
    neg = n < 0
    n = abs(n)
    while n > 0:
        result = digits[n % base] + result
        n //= base
    return "-" + result if neg else result

def from_base(s, base):
    return int(s, base) if base <= 36 else None

def sha256_hash(text):
    import hashlib
    return hashlib.sha256(text.encode()).hexdigest()

def md5_hash(text):
    import hashlib
    return hashlib.md5(text.encode()).hexdigest()

def base64_encode(text):
    import base64
    return base64.b64encode(text.encode()).decode()

def base64_decode(text):
    import base64
    try:
        return base64.b64decode(text).decode()
    except:
        return "Invalid base64"

def rot13(text):
    return caesar_cipher(text, 13)

def text_to_ascii(text):
    return [ord(c) for c in text]

def ascii_to_text(codes):
    return "".join(chr(c) for c in codes)

def count_words(text):
    return len(text.split())

def count_sentences(text):
    import re
    return len(re.findall(r'[.!?]+', text))

def count_paragraphs(text):
    return len([p for p in text.split('\n\n') if p.strip()])

def remove_duplicate_words(text):
    words = text.split()
    seen = set()
    result = []
    for w in words:
        if w.lower() not in seen:
            seen.add(w.lower())
            result.append(w)
    return " ".join(result)

def reverse_words(text):
    return " ".join(text.split()[::-1])

def reverse_word_order(text):
    return " ".join(text.split()[::-1])

def sort_words(text):
    return " ".join(sorted(text.split(), key=str.lower))

def shuffle_words(text):
    words = text.split()
    random.shuffle(words)
    return " ".join(words)

def acronym(text):
    return "".join(w[0].upper() for w in text.split() if w)

def capitalize_title(text):
    small_words = {"a", "an", "the", "and", "or", "but", "in", "on", "at", "to", "for", "of", "by", "with"}
    words = text.split()
    result = []
    for i, w in enumerate(words):
        if i == 0 or i == len(words) - 1 or w.lower() not in small_words:
            result.append(w.capitalize())
        else:
            result.append(w.lower())
    return " ".join(result)

def detect_language(text):
    languages = {
        "english": "the and is in it you that was for are",
        "spanish": "el la los las que y en por con su",
        "french": "le la les des dans est que pour avec sur",
        "german": "der die das und mit auf fur ist nicht",
        "italian": "il la le gli che e per con nel sul",
        "portuguese": "o a os as que para com por no na",
        "dutch": "de het een van en met voor niet op",
        "russian": "и в не на что с как это он мы",
        "japanese": "の は を が に で と も から する",
    }
    words = set(text.lower().split())
    best_score = 0
    best_lang = "Unknown"
    for lang, common in languages.items():
        score = sum(1 for w in common.split() if w in words)
        if score > best_score:
            best_score = score
            best_lang = lang
    return best_lang

def spell_check(text):
    common_words = {
        "the", "be", "to", "of", "and", "a", "in", "that", "have", "it",
        "for", "not", "on", "with", "he", "as", "you", "do", "at", "this",
        "but", "his", "by", "from", "they", "we", "say", "her", "she", "or",
        "an", "will", "my", "one", "all", "would", "there", "their", "what",
        "so", "up", "out", "if", "about", "who", "get", "which", "go", "me",
        "when", "make", "can", "like", "time", "no", "just", "him", "know",
        "take", "people", "into", "year", "your", "good", "some", "could",
        "them", "see", "other", "than", "then", "now", "look", "only", "come",
        "its", "over", "think", "also", "back", "after", "use", "two", "how",
        "our", "work", "first", "well", "way", "even", "new", "want", "because",
        "any", "these", "give", "day", "most", "us", "great", "between", "need",
    }
    words = text.split()
    misspelled = [w for w in words if w.lower() not in common_words]
    return misspelled

def word_frequency(text):
    freq = {}
    for w in text.lower().split():
        w = w.strip(".,!?;:'\"()[]{}")
        if w:
            freq[w] = freq.get(w, 0) + 1
    return dict(sorted(freq.items(), key=lambda x: -x[1]))

def longest_word(text):
    words = text.split()
    if not words:
        return ""
    return max(words, key=len)

def shortest_word(text):
    words = text.split()
    if not words:
        return ""
    return min(words, key=len)

def most_common_letter(text):
    letters = [c.lower() for c in text if c.isalpha()]
    if not letters:
        return None
    from collections import Counter
    return Counter(letters).most_common(1)[0]

def has_url(text):
    return "http://" in text.lower() or "https://" in text.lower() or "www." in text.lower()

def has_email(text):
    return "@" in text and "." in text[text.index("@"):]

def extract_numbers(text):
    import re
    return [int(x) for x in re.findall(r'\d+', text)]

def extract_emails(text):
    import re
    return re.findall(r'[\w.+-]+@[\w-]+\.[\w.-]+', text)

def extract_urls(text):
    import re
    return re.findall(r'https?://(?:[-\w.]|(?:%[\da-fA-F]{2}))+', text)

def remove_html_tags(text):
    import re
    return re.sub(r'<[^>]+>', '', text)

def censor_bad_words(text):
    bad_words = {"bad", "evil", "terrible", "awful", "horrible", "nasty", "mean",
                 "stupid", "dumb", "ugly", "hate", "damn", "hell", "crap", "jerk"}
    words = text.split()
    result = []
    for w in words:
        if w.lower().strip(".,!?;:'\"") in bad_words:
            result.append("*" * len(w))
        else:
            result.append(w)
    return " ".join(result)

def suggest_emoji(text):
    emoji_map = {
        "happy": "😊", "sad": "😢", "love": "❤️", "cool": "😎", "funny": "😂",
        "angry": "😠", "cry": "😭", "wink": "😉", "shock": "😮", "sleep": "😴",
        "music": "🎵", "pizza": "🍕", "cat": "🐱", "dog": "🐶", "tree": "🌳",
        "sun": "☀️", "moon": "🌙", "star": "⭐", "fire": "🔥", "water": "💧",
    }
    for word, emoji in emoji_map.items():
        if word in text.lower():
            return emoji
